//! Expected values were generated by libstdc++ (GCC 15) with the same seeds.

use vq::rng::{self, Mt19937_64, Normal};

#[test]
fn uniform_matches_libstdcpp() {
    let expected: [[u64; 3]; 6] = [
        [5, 243, 252145248],
        [6, 36, 118311656],
        [5, 230, 552242747],
        [5, 193, 1280305657],
        [2, 78, 1787067971],
        [2, 254, 2133852984],
    ];
    let mut rng = Mt19937_64::new(7);
    for row in expected {
        for (value, range) in row.into_iter().zip([7, 256, 2147483647]) {
            assert_eq!(rng::uniform_below(&mut rng, range), value);
        }
    }
}

#[test]
fn normal_f32_matches_libstdcpp() {
    let expected: [u32; 6] =
        [0x3fcf8233, 0x3fad0a16, 0x3fefa4f4, 0x3fa2be04, 0x3fbc4707, 0x3fb86534];
    let mut rng = Mt19937_64::new(11);
    let mut normal = Normal::<f32>::new(1.5, 0.25);
    for bits in expected {
        assert_eq!(normal.sample(&mut rng).to_bits(), bits);
    }
}

#[test]
fn normal_f64_matches_libstdcpp() {
    let expected: [u64; 6] = [
        0xbff749854eac3df8,
        0x3ffac7e54f560cbc,
        0xbf9ec75ee49e1cfe,
        0xbfbcd576897f68c3,
        0x3fdb64b97734cdca,
        0xbffcc911cd9b83e8,
    ];
    let mut rng = Mt19937_64::new(13);
    let mut normal = Normal::<f64>::standard();
    for bits in expected {
        assert_eq!(normal.sample(&mut rng).to_bits(), bits);
    }
}

#[test]
fn discrete_matches_libstdcpp() {
    let expected = [4, 1, 4, 4, 4, 4, 1, 1, 2, 4, 4, 2, 4, 1, 2, 4];
    let weights = [0.0, 3.0, 1.0, 0.0, 6.0, 0.5];
    let mut rng = Mt19937_64::new(17);
    for index in expected {
        assert_eq!(rng::discrete(&weights, &mut rng), index);
    }
}
